#wFamily { display: contents; }
.compact .win-family .fam-row { grid-template-columns: 34px 28px minmax(0, 1fr) minmax(78px, auto); gap: 4px; padding: 2px 1px; }
.compact .win-family .fr-name { white-space: nowrap; }
