/* The heart picker uses the win popup's measured height; smaller viewports can scroll. */
.modal-box.heart-compose { height: var(--heart-dialog-height, auto); max-height: calc(100dvh - 40px); padding: 16px 16px 12px; display: flex; flex-direction: column; justify-content: space-between; gap: 4px; }
