.heart-compose .note.small { font-size: 16px; line-height: 1.35; margin: 0; }
.heart-compose .msg-pick { gap: 6px; margin: 0; }
.heart-compose .msg-pick .mp { height: 38px; font-size: 17px; line-height: 1.2; padding: 5px 8px; border-width: 2px; border-radius: 14px; }
