/* ========== 11 tasks, stats, special tiles ========== */
.task-list { display: grid; gap: 10px; margin: 12px 0; text-align: left; }
.task { display: grid; grid-template-columns: 44px 1fr; gap: 10px; align-items: center; background: #fff; border-radius: 16px; padding: 10px 12px; box-shadow: 0 3px 0 var(--cream2); }
.task .t-ico { font-size: 30px; text-align: center; }
.task b { display: block; font-size: 18px; line-height: 1.2; }
.task small { font-size: 14px; color: var(--muted); font-weight: 700; }
.task .bar { display: block; height: 12px; background: #efe2c0; border-radius: 8px; margin: 6px 0 3px; overflow: hidden; }
.task .bar i { display: block; height: 100%; background: linear-gradient(90deg, #8be06a, #3fae2a); border-radius: 8px; transition: width .4s; }
.task.done { background: #e8f8dc; }
.chest-btn { display: flex; align-items: center; gap: 12px; width: 100%; text-align: left; background: #efe2c0; color: #6a5530; border-radius: 18px; padding: 10px 14px; font-size: 17px; font-weight: 800; margin-bottom: 8px; }
.chest-btn .chest-ico { font-size: 40px; filter: grayscale(.7); }
.chest-btn.ready { background: linear-gradient(#ffe27a, var(--gold)); color: #5a3a00; box-shadow: 0 5px 0 var(--gold-d); animation: chipPulse 1.1s ease-in-out infinite; }
.chest-btn.ready .chest-ico { filter: none; animation: wiggle .6s ease-in-out infinite; }
.chest-btn.opened { opacity: .75; }
.chest-btn.opened .chest-ico { filter: none; }
@keyframes wiggle { 25% { transform: rotate(-12deg) scale(1.1); } 75% { transform: rotate(12deg) scale(1.1); } }
.chest-open { font-size: 90px; line-height: 1; margin: 4px 0; }
.chest-open .lid { display: inline-block; animation: chestPop 1s cubic-bezier(.3,1.6,.5,1); }
@keyframes chestPop { 0% { transform: scale(.2) rotate(-30deg); } 40% { transform: scale(1.3) rotate(10deg); } 100% { transform: scale(1); } }
.chest-loot { display: flex; justify-content: center; gap: 14px; margin: 10px 0; }
.chest-loot div { background: #fff; border-radius: 16px; padding: 8px 18px; display: grid; justify-items: center; font-size: 30px; box-shadow: 0 3px 0 var(--cream2); animation: pop .5s .3s cubic-bezier(.3,1.6,.5,1) backwards; }
.chest-loot div + div { animation-delay: .5s; }
.chest-loot b { font-size: 26px; font-weight: 900; color: var(--green-d); }
.chest-loot small { font-size: 14px; color: var(--muted); font-weight: 700; }

.stats-card { background: var(--cream); color: var(--ink); border-radius: 20px; padding: 12px; margin-bottom: 14px; box-shadow: 0 4px 0 var(--cream2); }
.stats-card h3 { margin: 0 0 8px; font-size: 21px; text-align: center; }
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.stat { background: #fff; border-radius: 12px; padding: 6px 2px; display: grid; justify-items: center; text-align: center; }
.stat span { font-size: 22px; line-height: 1.1; }
.stat b { font-size: 18px; font-weight: 900; font-variant-numeric: tabular-nums; }
.stat small { font-size: 11.5px; color: var(--muted); font-weight: 700; line-height: 1.15; }

#board .tile.gold:not(.back) { background: linear-gradient(160deg, #fff8d0 0%, #ffe680 55%, #f2c230 100%); box-shadow: inset 0 0 0 2px #e0a800, 0 0 10px 2px rgba(255,200,0,.55); }
.tile.gold:not(.back) .face::after { content: '✨'; position: absolute; right: -6%; top: -8%; font-size: calc(var(--fs, 30px) * .32); line-height: 1; }
#board .tile.sp-joker:not(.back) { background: linear-gradient(160deg, #f3ecff 0%, #dccbff 60%, #c2a8ff 100%); }
.emo.sp { animation: spBob 1.6s ease-in-out infinite; display: inline-block; }
@keyframes spBob { 50% { transform: scale(1.1) rotate(-4deg); } }
/* a face-down tile that matches at once: it flips open while it flies */
.tile.flying.reveal .face { animation: faceReveal .26s ease-out; }
@keyframes faceReveal { from { transform: scaleX(0); } 60% { transform: scaleX(1.1); } }
/* ice, lock and key */
.tile .ob { position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: 2; }
.tile .ob::after { position: absolute; line-height: 1; font-size: calc(var(--fs, 30px) * .42); filter: drop-shadow(0 1px 1px rgba(0,0,0,.35)); }
.tile .ob[data-k^="ice"] { background: linear-gradient(155deg, rgba(225,245,255,.62) 0%, rgba(160,215,250,.5) 55%, rgba(120,190,240,.55) 100%); box-shadow: inset 0 0 0 3px rgba(140,205,255,.95), inset 0 0 14px 2px rgba(255,255,255,.9); }
.tile .ob[data-k="ice2"] { background: linear-gradient(155deg, rgba(225,245,255,.8) 0%, rgba(160,215,250,.72) 55%, rgba(110,180,235,.75) 100%); box-shadow: inset 0 0 0 5px rgba(120,195,255,1), inset 0 0 18px 4px rgba(255,255,255,.95); }
.tile .ob[data-k="ice"]::after { content: '❄️'; right: 2%; bottom: 3%; font-size: calc(var(--fs, 30px) * .5); }
.tile .ob[data-k="ice2"]::after { content: '❄️❄️'; right: 2%; bottom: 3%; font-size: calc(var(--fs, 30px) * .32); }
.tile .ob[data-k="lock"] { background: rgba(70,45,10,.26); box-shadow: inset 0 0 0 4px #9a6b1f; }
.tile .ob[data-k="lock"]::after { content: '🔒'; right: -4%; bottom: -3%; font-size: calc(var(--fs, 30px) * .62); filter: drop-shadow(0 2px 3px rgba(0,0,0,.5)); }
.tile .ob[data-k="key"] { box-shadow: inset 0 0 0 3px #e0a800, 0 0 10px 2px rgba(255,200,0,.6); }
.tile .ob[data-k="key"]::after { content: '🔑'; left: -4%; top: -6%; font-size: calc(var(--fs, 30px) * .46); }
/* the alarm clock: a badge with the moves left (red and pulsing for the last 5) */
#board .tile.clocked { box-shadow: 0 0 0 3px #ff7a2f, 0 0 12px 3px rgba(255,122,47,.6); }
#clockBadge { position: absolute; z-index: 1999999; display: flex; align-items: center; gap: 1px; padding: 1px 6px 1px 3px; border-radius: 99px; background: #fff3e6; border: 2px solid #ff7a2f; box-shadow: 0 2px 5px rgba(0,0,0,.4); line-height: 1.15; pointer-events: none; }
#clockBadge b { color: #b23c00; font-weight: 900; font-variant-numeric: tabular-nums; min-width: 1.2em; text-align: center; }
#clockBadge.urgent { background: #ff4d3d; border-color: #b51d10; animation: ckPulse .8s ease-in-out infinite; }
#clockBadge.urgent b { color: #fff; }
@keyframes ckPulse { 50% { transform: scale(1.18); } }
.tile .ob-open { position: absolute; right: -4%; bottom: -3%; z-index: 3; font-size: calc(var(--fs, 30px) * .62); line-height: 1; pointer-events: none; filter: drop-shadow(0 2px 3px rgba(0,0,0,.45)); animation: obOpen 1.1s ease forwards; }
@keyframes obOpen { 0% { transform: scale(1); } 25% { transform: scale(1.6) rotate(-14deg); } 55% { transform: scale(1.25); opacity: 1; } 100% { transform: scale(1); opacity: 0; } }
.ob-crack { position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: 3; background: radial-gradient(circle, rgba(255,255,255,.95) 0%, rgba(180,225,255,.7) 40%, transparent 70%); animation: crack .55s ease-out forwards; }
@keyframes crack { from { opacity: 1; transform: scale(.6); } to { opacity: 0; transform: scale(1.5); } }
#board .tile.obhint { animation: nudgeShake 1.3s ease-in-out 1; box-shadow: 0 0 0 4px #7fd0ff, 0 0 16px 6px rgba(120,200,255,.85); }
.nt-ico { font-size: 72px; line-height: 1.1; animation: giftWiggle 1.4s ease-in-out infinite; display: inline-block; }
.clock-help { padding: 16px; }
.clock-help .nt-ico { font-size: 40px; }
.clock-help h2 { font-size: 26px; }
.clock-help p { font-size: 16px; line-height: 1.3; margin: 6px 0 10px; }
.clock-help .big-btn { padding: 11px 16px; margin-top: 8px; }
.clock-help .big-btn b { font-size: 24px; }
.clock-help .link-btn { margin-top: 2px; padding: 6px 16px; }
/* Animated tile lessons, using the same pictures as the board. */
.tile-help { padding: 18px 16px; }
.tile-help h2 { font-size: 26px; line-height: 1.15; }
.tile-help p { font-size: 17px; line-height: 1.3; margin: 8px 0; }
.tile-help .big-btn b { font-size: 23px; }
.tile-help .lesson-reminder, .clock-help .lesson-reminder { font-size: 14px; color: var(--muted); margin: 0 0 6px; font-weight: 800; }
.lesson-demo { background: #e4f0df; border: 1px solid #b4cba6; border-radius: 16px; padding: 8px 8px 4px; margin: 10px 0; }
.lesson-scene { position: relative; height: 112px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; transition: opacity .18s; }
.lesson-scene.lz-fade { opacity: 0; }
.lesson-demo[data-lesson="ice"] .lesson-scene { height: 124px; }
.lesson-demo .lesson-ice-board { display: grid; grid-template-columns: 38px; gap: 3px; }
.lesson-ice-board .lesson-tile { height: 38px; }
.lesson-board { display: flex; align-items: center; justify-content: center; gap: 9px; min-height: 52px; }
.lesson-tile { position: relative; display: inline-flex; width: 38px; height: 48px; align-items: center; justify-content: center; border-radius: 7px; background: linear-gradient(160deg, #fffef9 0%, #fbf4e2 55%, #efe2c0 100%); box-shadow: 2px 3px 0 #c5ac75; flex: none; }
.lesson-face { display: flex; width: 30px; height: 36px; align-items: center; justify-content: center; font-size: 27px; }
.lesson-face svg { width: 100%; height: 100%; }
/* face-down in the lessons: the same back as on the board (and the sunflower back in that theme) */
.lesson-back { background: radial-gradient(circle at 50% 50%, #ffe08a 0 9%, #e8b13a 10% 14%, transparent 15%), repeating-linear-gradient(45deg, rgba(255,255,255,.13) 0 2px, transparent 2px 8px), repeating-linear-gradient(-45deg, rgba(255,255,255,.13) 0 2px, transparent 2px 8px), linear-gradient(160deg, #3dbb90, #1b8063); outline: 2px solid #fff9e9; }
.lesson-back .lesson-face { visibility: hidden; }
.lesson-tray { display: flex; gap: 5px; padding: 5px; background: #805431; border-radius: 10px; }
.lesson-slot { display: flex; align-items: center; justify-content: center; width: 36px; height: 40px; border-radius: 5px; background: #573b28; }
.lesson-slot .lesson-tile { width: 31px; height: 35px; box-shadow: 1px 2px 0 #c5ac75; }
.lesson-slot .lesson-face { width: 25px; height: 29px; font-size: 22px; }
/* the lesson scene (specials.js): a tile glides, the hand taps, badges as on the board */
.lesson-tile.lz-moving { z-index: 3; transition: transform .38s cubic-bezier(.35,.1,.25,1), opacity .3s ease-in; }
.lz-badge { position: absolute; z-index: 2; line-height: 1; font-size: 19px; filter: drop-shadow(0 1px 1px rgba(0,0,0,.35)); }
.lz-keyb { left: -8px; top: -9px; }
.lz-lockb { right: -8px; bottom: -7px; font-size: 22px; }
.lz-key { box-shadow: inset 0 0 0 2.5px #e0a800, 0 0 8px 2px rgba(255,200,0,.55), 2px 3px 0 #c5ac75; }
.lz-key.lz-glow { animation: lz-keyglow 1.1s ease-in-out infinite; }
@keyframes lz-keyglow { 50% { box-shadow: inset 0 0 0 2.5px #e0a800, 0 0 15px 6px rgba(255,200,0,.95), 2px 3px 0 #c5ac75; } }
.lz-lock::before { content: ''; position: absolute; inset: 0; z-index: 1; border-radius: inherit; background: rgba(70,45,10,.32); box-shadow: inset 0 0 0 3px #9a6b1f; transition: opacity .4s; }
.lz-lock.lz-open::before { opacity: 0; }
.lz-shut .lz-lockb { animation: lz-rattle .5s ease; }
@keyframes lz-rattle { 20%, 60% { transform: rotate(-16deg); } 40%, 80% { transform: rotate(16deg); } }
.lz-open .lz-lockb { animation: lz-unlock 1.1s ease forwards; }
@keyframes lz-unlock { 0% { transform: scale(1); } 25% { transform: scale(1.6) rotate(-14deg); } 55% { transform: scale(1.25); opacity: 1; } 100% { transform: scale(1); opacity: 0; } }
.lz-clock { box-shadow: 0 0 0 3px #ff7a2f, 0 0 10px 2px rgba(255,122,47,.5), 2px 3px 0 #c5ac75; }
.lz-clock.lz-glow { animation: lz-ckglow 1.2s ease-in-out infinite; }
@keyframes lz-ckglow { 50% { box-shadow: 0 0 0 3px #ff7a2f, 0 0 16px 6px rgba(255,122,47,.85), 2px 3px 0 #c5ac75; } }
.lz-ck { position: absolute; z-index: 2; top: -10px; right: -17px; display: flex; align-items: center; gap: 1px; padding: 0 5px 0 2px; border-radius: 99px; background: #fff3e6; border: 2px solid #ff7a2f; box-shadow: 0 2px 4px rgba(0,0,0,.35); font-size: 13px; line-height: 1.3; font-weight: 900; color: #b23c00; white-space: nowrap; }
.lz-ck i { font-style: normal; font-variant-numeric: tabular-nums; min-width: .75em; text-align: center; }
.lz-ck.lz-tick { animation: lz-tick .5s ease; }
@keyframes lz-tick { 40% { transform: scale(1.5); background: #ffd23f; } }
.lz-ck.lz-same { animation: lz-same .7s ease; }
@keyframes lz-same { 25% { transform: rotate(-10deg); } 50% { transform: rotate(10deg); } 75% { transform: rotate(-5deg); } }
.lz-ck.lz-done { padding: 0 6px; background: #5ee07f; border-color: #2c9b4f; color: #fff; }
.lz-ice2::before, .lz-ice1::before, .lz-melted::before { content: ''; position: absolute; inset: 0; z-index: 1; border-radius: inherit; }
.lz-ice2::before { background: linear-gradient(155deg, rgba(225,245,255,.82) 0%, rgba(160,215,250,.74) 55%, rgba(110,180,235,.78) 100%); box-shadow: inset 0 0 0 4px rgba(120,195,255,1), inset 0 0 12px 3px rgba(255,255,255,.95); }
.lz-ice1::before, .lz-melted::before { background: linear-gradient(155deg, rgba(225,245,255,.62) 0%, rgba(160,215,250,.5) 55%, rgba(120,190,240,.55) 100%); box-shadow: inset 0 0 0 2.5px rgba(140,205,255,.95), inset 0 0 10px 2px rgba(255,255,255,.9); }
.lz-melted::before { animation: lz-melt .5s ease forwards; }
@keyframes lz-melt { to { opacity: 0; } }
.lz-iceb { right: -7px; bottom: -6px; font-size: 15px; letter-spacing: -2px; }
.lz-melted .lz-iceb { animation: lz-melt .4s ease forwards; }
.lz-ice2.lz-glow { animation: lz-iceglow 1.2s ease-in-out infinite; }
@keyframes lz-iceglow { 50% { box-shadow: 0 0 12px 4px rgba(120,195,255,.9), 2px 3px 0 #c5ac75; } }
.lz-badge.lz-tick { animation: lz-tick2 .45s ease; }
@keyframes lz-tick2 { 40% { transform: scale(1.5); } }
