.cz-tray { position: absolute; left: 50%; top: 8px; transform: translateX(-50%); z-index: 2; display: grid; grid-template-columns: repeat(4, 32px); gap: 4px; padding: 4px; border-radius: 11px;
  background: linear-gradient(#8a5a33, #6b4224); box-shadow: inset 0 3px 6px rgba(0,0,0,.45), 0 3px 0 #4a2d17; transition: box-shadow .3s; --sfs: 20px; }
