.cz-tray .tmini.cz-pop { animation: popout .23s ease forwards; }
.cz-board { position: absolute; left: 0; right: 0; bottom: 0; top: 60px; overflow: hidden; }
.cz-ov .tile { pointer-events: none; }
.cz-ov .tile.cz-moving { transition: transform .38s cubic-bezier(.35,.1,.25,1), opacity .25s; }
