.cz-board .tile { pointer-events: none; }
.cz-board .tile.cz-moving { transition: transform .38s cubic-bezier(.35,.1,.25,1), opacity .25s; }
.cz-board .tile.cz-pop { opacity: 0; transition: opacity .2s; }
