/* a tile whose picture the player has not seen: no picture in the film */
.cz-board .tile.cz-unseen .face { display: grid; place-items: center; }
.cz-q { font-size: calc(var(--fs, 30px) * .8); font-weight: 900; color: #b9a77c; line-height: 1; }
.cz-board .tile.cz-peek { box-shadow: 0 0 0 2px #ffb300, 0 0 8px 2px rgba(255,179,0,.7); }
.cz-ov { position: absolute; inset: 0; pointer-events: none; z-index: 950000; }
.cz-mark { position: absolute; border-radius: 14%; animation: czGlow 1s ease-in-out infinite alternate; }
.cz-mark.cz-good { box-shadow: 0 0 0 3px #2ecc71, 0 0 12px 4px rgba(46,204,113,.85); }
.cz-mark.cz-info { box-shadow: 0 0 0 3px #4fc3ff, 0 0 12px 4px rgba(80,200,255,.85); }
.cz-mark.cz-bad { box-shadow: 0 0 0 3px #ff4d4d, 0 0 12px 4px rgba(255,60,60,.85); }
.cz-mark.cz-cone { box-shadow: 0 0 0 3px #ffb300, 0 0 10px 3px rgba(255,179,0,.8); }
@keyframes czGlow { from { opacity: .55; } to { opacity: 1; } }
.cz-ck { position: absolute; transform: translate(-50%, -100%); display: flex; align-items: center; gap: 1px; padding: 0 5px 0 2px; border-radius: 99px; background: #fff3e6; border: 2px solid #ff7a2f; box-shadow: 0 2px 4px rgba(0,0,0,.35); font-size: 12px; line-height: 1.3; font-weight: 900; color: #b23c00; white-space: nowrap; }
