.cz-ck.lz-tick { animation: czTick .5s ease; }
@keyframes czTick { 40% { background: #ffd23f; transform: translate(-50%, -100%) scale(1.4); } }
.cz-ck.cz-out { background: #e53935; border-color: #fff; color: #fff; animation: shake .3s 3; }
.cz-stage .lz-hand { z-index: 990000; }
.cz-stage .lz-ripple, .cz-stage .lz-spark { z-index: 985000; }
.cz-verdict { position: absolute; left: 50%; top: 58%; z-index: 980000; width: 62px; height: 62px; margin: -31px 0 0 -31px; border-radius: 50%; display: grid; place-items: center; font-size: 36px; font-weight: 900; color: #fff; opacity: 0; transform: scale(.4); transition: transform .35s cubic-bezier(.3,1.6,.5,1), opacity .2s; pointer-events: none; box-shadow: 0 4px 0 rgba(0,0,0,.2), 0 0 0 4px #fff; }
